inline const char* Translate(int language, const char* text) {
    if (!text || SpartanLauncher::Normalize(language) == 0) return text;
    const std::string_view key{text};
    const auto entry = std::lower_bound(std::begin(Catalog), std::end(Catalog), key,
        [](const Entry& item, std::string_view value) { return item.en < value; });
    if (entry == std::end(Catalog) || key != entry->en) return text;
    return language == 1 ? entry->pt : entry->es;
}
// Startup dialogs use the same file semantics as SpartanSettings::Load, before GPU init.
inline int ReadLanguage(std::istream& config) {
    int language = 0;
    for (std::string line; std::getline(config, line);) {
        line.erase(line.find_last_not_of(" \t\r\n") + 1);
        if (line.starts_with("launcher_language="))
            language = SpartanLauncher::Parse(line.substr(18));
    }
    return language;
}
// Stable widget identity across languages. Hidden IDs are already language independent.
inline std::string Label(int language, const char* text) {
    if (std::string_view(text).starts_with("##")) return text;
    return std::string(Translate(language, text)) + "###" + text;
}
